        pathParameters = listOf(),
        query = listOf(ContractQuery("profession", required = false)),
        request = Unit.serializer(),
        response = ListSerializer(SpecialtyDto.serializer()),
    )

    /**
     * Which side of the app this account opens (ADR-0101, 0.128.0), for a client with one door: LumeMedLink signs
     * patients and clinicians in through the same screen and the same IdP tenant, and asks this right after.
     * `CLINICIAN` for a clinical-app token and for a LumeMedLink account LumeMed staff linked to a clinician
     * (`linkIdentity`, ADR-0090) — the link wins when the same person is also somebody's patient. `PATIENT` for a
     * LumeMedLink account enrolled with a clinic's code. `NONE` for one that is neither yet, or suspended: it
     * redeems a code (`redeemPatientEnrolment`) or opens nothing. **It decides what you draw, never what you may
     * do**: every route still refuses what is not this account's. It needs no `X-Lume-Installation`, since it is
     * how you learn which phone enrolment to call (`enrolMyPatientPhone` or `enrolMyPhone`).
     */
    val GET_MY_ROLE: ContractOperation<Unit, MyRoleDto> = ContractOperation(
        id = "getMyRole",
        verb = ContractVerb.GET,
        path = "/v1/me/role",
        pathParameters = listOf(),
        query = listOf(),
        request = Unit.serializer(),
        response = MyRoleDto.serializer(),
    )

